import{_ as e,o as d,c as r,a2 as a}from"./chunks/framework.gtmkOXzY.js";const f=JSON.parse('{"title":"Jobs and missions","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/jobs.md","filePath":"ms-flightsim/jobs.md","lastUpdated":null}'),i={name:"ms-flightsim/jobs.md"};function o(n,t,s,l,c,h){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="jobs-and-missions" tabindex="-1">Jobs and missions <a class="header-anchor" href="#jobs-and-missions" aria-label="Permalink to &quot;Jobs and missions&quot;">​</a></h1><p>There are 16 paid missions plus the Airshow event. Missions are started from the Jobs tab, which opens at the cargo / job NPC of an airport. Every paid mission can be flown with a co-pilot: each pilot is paid on their own rank, plus a 20% crew bonus (<code>coPilotBonusPct</code>).</p><p>Base pay is the default before rank, crew bonus, the 10% company cut and your multipliers. Flying without ATC clearance while a controller is on duty halves it, and a damaged aircraft can reduce it to half. The last amount in a pay cell is the completion bonus. Base pay is the default before rank, company cut and your multipliers; change any of it in <code>Config.Payouts</code>.</p><table tabindex="0"><thead><tr><th>Mission</th><th>Licence</th><th>Minimum rank</th><th>Extra requirement</th><th>Default base pay</th></tr></thead><tbody><tr><td>Air Cargo Delivery</td><td>Plane</td><td>—</td><td>—</td><td>$800 + $300/km</td></tr><tr><td>Banner Towing</td><td>Plane</td><td>—</td><td>—</td><td>$600 + $200 per waypoint + $400</td></tr><tr><td>Airshow (leader + up to 3 wingmen)</td><td>Plane</td><td>—</td><td>—</td><td>No pay — an event, started from the Other tab at LSIA</td></tr><tr><td>Passenger / Air Taxi</td><td>Plane</td><td>Private</td><td>Turbine rating</td><td>$700 + $500/km + tip</td></tr><tr><td>Sightseeing</td><td>Plane</td><td>Private</td><td>—</td><td>$1,200 + bonuses</td></tr><tr><td>Aerial Survey</td><td>Plane</td><td>First Officer</td><td>—</td><td>$400 per point + $600</td></tr><tr><td>Crop Dusting</td><td>Plane</td><td>First Officer</td><td>—</td><td>$400 per pass + $1,500</td></tr><tr><td>Sky Writing</td><td>Plane</td><td>Senior First Officer</td><td>—</td><td>$3,500 + $200 per point + $1,500</td></tr><tr><td>Offshore Supply (seaplane)</td><td>Plane</td><td>Senior First Officer</td><td>—</td><td>$3,200 + $450 per box + $1,200</td></tr><tr><td>Captain Flight (airliner)</td><td>Plane</td><td>Captain</td><td>Jet rating</td><td>$5,000 + time bonus</td></tr><tr><td>Aerial Firefighting (MS41s)</td><td>Plane</td><td>Captain</td><td>Turbine rating</td><td>$6,000 + $600 per fire + $3,000</td></tr><tr><td>Smuggling</td><td>Plane</td><td>Instructor</td><td>5 legal jobs, flown in a Streamer216</td><td>$6,000 black money (no company cut)</td></tr><tr><td>Heavy Lift</td><td>Helicopter</td><td>Senior First Officer</td><td>Skylift rating</td><td>$5,000 + $500/km</td></tr><tr><td>Emergency Supply Drop</td><td>Helicopter</td><td>Captain</td><td>—</td><td>$4,500 + $600 per crate + $1,500</td></tr><tr><td>MedEvac / SAR</td><td>Helicopter</td><td>Flight Captain</td><td>Medevac rating</td><td>$8,000 + $800 per extra survivor</td></tr><tr><td>Wildfire Suppression</td><td>Helicopter</td><td>Senior Flight Captain</td><td>Firefighting rating</td><td>$4,000 + $800 per fire + $2,000</td></tr><tr><td>VIP Extraction</td><td>Helicopter</td><td>Senior Flight Captain</td><td>—</td><td>$12,000 + $6,000</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Emergency services</strong>: players on the ambulance or fire job who hold a helicopter licence skip the rank and rating for MedEvac; fire-job players also skip them for Wildfire Suppression. Their job board then shows only those missions.</li><li><strong>Aerial Firefighting</strong> needs the <code>ms41s</code> resource (on <code>ms_aircraft_core</code>): scoop water and drop it on a fire front of 12 fires. Without it, the job says the water bomber is not available. Fire-job players with a plane licence can fly it too.</li><li><strong>Offshore Supply</strong> is solo or duo. With the MS41s running, the pilot chooses between the Dodo and the MS41s at the start.</li><li><strong>Water operations</strong>: amphibious aircraft listed in <code>Config.WaterOps.models</code> can land on and take off from water with no low-flying or crash penalty. The MS41s adds itself; add <code>&#39;dodo&#39;, &#39;seabreeze&#39;, &#39;tula&#39;</code> to include the stock seaplanes.</li><li><strong>Ground Services</strong> is a separate job anyone can do, no licence needed: refuel, pushback, cargo, baggage, catering, water, stairs and ground power for aircraft at the stands. Each service pays $140–$320 (±10%). See <a href="./ground-services">Ground services</a>.</li><li><strong>Heavy Lift</strong> can also be started with <code>/heavylift</code>.</li><li>Every mission can be switched off in <code>Config.Features</code>. The <code>/adminps</code> <strong>Jobs</strong> tab covers all of them except Offshore Supply and the Airshow. Ground Services is switched with <code>Config.GroundServices.enabled</code>.</li></ul>',6)])])}const u=e(i,[["render",o]]);export{f as __pageData,u as default};
